{
  "county_id": "HVA07",
  "actions": [
    {
      "action_id": "pathway-timestamps",
      "action": "Proposed: Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "The brief says the earliest stage where Kanta-Häme is clearly worse than the country is early detection, and time from referral to diagnosis and from diagnosis to first treatment is not published by county, so the Goal 3 indicator cannot be checked from open data.",
      "owner_role": "Accountable owner: FICAN with THL and the Finnish Cancer Registry.",
      "indicator": "Indicator to monitor: Share of new cancer cases with all four timestamps recorded.",
      "roadmap_measure": "3.2.1"
    },
    {
      "action_id": "timed-pathways",
      "action": "Proposed: Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The portfolio recommends timed-pathways for Kanta-Häme, with a model scenario of about 8 deaths postponed per year (range 1.2-16) at an assumed EUR 253,436 a year, and the county waits over 6 months for specialised care at 56 per 10 000 inhabitants against 36 nationally.",
      "owner_role": "Accountable owner: Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Indicator to monitor: Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Proposed: Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Cervical screening participation in Kanta-Häme is 70.6% against the 80% target, and the portfolio picks self-sampling for the county with an expected gain of 1.5-4.5 percentage points, closing about 32% of the gap.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    }
  ],
  "evidence_does_not_support": "For self-sampling, the Finnish gain over a reminder letter is about 3 points, far smaller than the international pooled estimate."
}

